import { readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { test, expect } from '@playwright/test';
import { findRepoRoot } from '@aitp/shared';

/**
 * THE SMOKE MANIFEST IS DERIVED, AND THIS IS WHAT HOLDS IT TO ITS SOURCES.
 *
 * `config/apps/ecom/smoke.json` is generated by `pnpm build:ecom-smoke` from the
 * captures and the QA sheet. It is checked in because the suite must run on a
 * machine with neither — a clean clone has no `artifacts/` and the workbook may
 * never enter the repo — and a checked-in derived file is a second copy that can
 * drift from what generated it.
 *
 * So the assertions below are about the things a drift would break: the counts
 * STEP 0 measured, the shape every spec reads, and the one property that makes the
 * file safe to commit at all — that it carries no live data.
 */

const ROOT = findRepoRoot();
const MANIFEST = path.join(ROOT, 'config', 'apps', 'ecom', 'smoke.json');

interface SmokeEntry {
  caseId: string;
  module: string;
  entity: string;
  url: string;
  kind: string;
  expectGrid?: boolean;
  expectedColumns?: string[];
}
interface Manifest {
  schemaVersion: number;
  application: string;
  generatedFrom: { captureSessions: string[]; statesConsidered: number; sheetRows: number };
  listLoad: SmokeEntry[];
  createOpens: SmokeEntry[];
  named: Array<{ caseId: string; kind: string; route: string }>;
  notAModuleScreen: Array<{ module: string; why: string }>;
  noCreateControl: Array<{ module: string; entity: string; why: string }>;
}

const manifest = (): Manifest => JSON.parse(readFileSync(MANIFEST, 'utf8')) as Manifest;

test.describe('the ecom smoke manifest @unit', () => {
  test('M1: the counts are the ones STEP 0 measured', () => {
    // wrong: a manifest that drifted from the measurement. These three numbers are
    // the whole scope of the suite — 29 modules, 28 with an addressable create
    // trigger, 5 named auth/dashboard cases — and a silent change to any of them
    // changes what is tested without anybody deciding to. The generator refuses to
    // write a different count; this is what notices if the FILE changes afterwards.
    const m = manifest();
    expect(m.listLoad).toHaveLength(29);
    expect(m.createOpens).toHaveLength(28);
    expect(m.named).toHaveLength(5);
    // 29 modules, 28 with a create trigger: the one without is the module that
    // genuinely has no create control, not a gap in the captures.
    expect(m.noCreateControl).toHaveLength(1);
    expect(m.noCreateControl[0]!.entity).toBe('QuotationComparison');
  });

  test('M2: every entry has what a spec reads, and every URL is a module path', () => {
    // wrong: one entry missing a field. The specs are data-driven, so a missing
    // `url` becomes `page.goto(undefined)` and a missing `caseId` becomes a test
    // named `undefined` — both of which run and report, which is worse than
    // failing. A URL that is not `/admin/domains/<Entity>` would navigate
    // somewhere nobody chose.
    const m = manifest();
    for (const entry of [...m.listLoad, ...m.createOpens]) {
      expect(entry.caseId, JSON.stringify(entry)).toMatch(/^[A-Z][A-Z0-9]*-\d+$/);
      expect(entry.entity).toMatch(/^[A-Za-z]+$/);
      expect(entry.url).toBe(`/admin/domains/${entry.entity}`);
      expect(entry.module.length).toBeGreaterThan(0);
    }
    for (const entry of m.named) {
      expect(entry.caseId).toMatch(/^(AUTH|DASH)-\d+$/);
      expect(entry.route.startsWith('/')).toBe(true);
    }
  });

  test('M3: case ids and entities are unique, so no module is tested twice or missed', () => {
    // wrong: two entries for one entity and none for another — which a hand-edited
    // map produces easily and which no count would catch, because the TOTAL stays
    // 29. The coverage claim is per module, so the identity of the 29 matters as
    // much as there being 29.
    const m = manifest();
    const entities = m.listLoad.map((e) => e.entity);
    expect(new Set(entities).size).toBe(entities.length);
    const caseIds = m.listLoad.map((e) => e.caseId);
    expect(new Set(caseIds).size).toBe(caseIds.length);
    // Every create-opens entry is one of the list-load modules, never a new one.
    for (const entry of m.createOpens) expect(entities).toContain(entry.entity);
  });

  test('M4: it carries NO live data — only identifiers, paths and field names', () => {
    // wrong: a record value in a checked-in file. The captures hold real customer
    // data and the workbook holds the QA's; the manifest is derived from both and
    // is the one artefact of this batch that enters the repository. So the file is
    // scanned for the shapes a leak would take rather than trusted to have been
    // built carefully.
    const raw = readFileSync(MANIFEST, 'utf8');
    expect(raw.length, 'the manifest is empty — the scan had no subject').toBeGreaterThan(500);
    // No email address, no URL with a host, no long free-text sentence.
    expect(raw).not.toMatch(/[\w.+-]+@[\w-]+\.[\w.]+/);
    expect(raw).not.toMatch(/https?:\/\//);
    // Expected columns are FIELD names: short, and none is a sentence.
    for (const entry of manifest().listLoad) {
      for (const column of entry.expectedColumns ?? []) {
        expect(column.length, `"${column}" is too long to be a column name`).toBeLessThan(60);
        expect(column.split(/\s+/).length, `"${column}" reads as a sentence`).toBeLessThan(7);
      }
    }
  });

  test('M5: it names the captures it was built from, and they are still on disk', () => {
    // wrong: a manifest nobody can re-derive. A number quoted from it is a claim
    // about a particular set of captures, and welding the two is the only thing
    // that lets a reader check it later (§"weld a headline number to the
    // assumption it was measured under"). A session that has been deleted is
    // reported rather than ignored — it means the manifest can no longer be
    // reproduced, which a reader needs to know BEFORE they trust its numbers.
    const m = manifest();
    expect(m.generatedFrom.captureSessions.length).toBeGreaterThan(0);
    expect(m.generatedFrom.statesConsidered).toBeGreaterThan(0);
    expect(m.generatedFrom.sheetRows).toBeGreaterThan(0);

    const dir = path.join(ROOT, 'artifacts', 'ecom', 'inspect');
    let onDisk: string[] = [];
    try {
      onDisk = readdirSync(dir);
    } catch {
      // artifacts/ is gitignored, so a clean clone has none. That is EXPECTED and
      // is not a failure: the manifest is checked in precisely so the suite runs
      // without them. The assertion only applies where the captures exist.
      test.info().annotations.push({
        type: 'captures-absent',
        description: `${dir} does not exist on this machine, so the manifest's sources cannot be re-checked here`,
      });
      return;
    }
    const missing = m.generatedFrom.captureSessions.filter((s) => !onDisk.includes(s));
    expect(
      missing,
      `capture sessions named by the manifest are gone: ${missing.join(', ')}`,
    ).toEqual([]);
  });

  test('M6: PutAway is the only module whose grid is not expected, and it says why', () => {
    // wrong: asserting a grid on every list page. PutAway's list was never captured
    // without a dialog open, so no evidence says a grid renders there — and a
    // smoke test that asserted one would fail for a reason that is about the
    // capture rather than about the application. The flag is per entry rather than
    // a special case in the spec, so the exception is data a reader can see.
    const m = manifest();
    const withoutGrid = m.listLoad.filter((e) => e.expectGrid === false).map((e) => e.entity);
    expect(withoutGrid).toEqual(['PutAway']);
    // And the rest DO expect one, or the flag is doing nothing.
    expect(m.listLoad.filter((e) => e.expectGrid === true)).toHaveLength(28);
  });
});
